import { z } from "zod";
import type { Db } from "./db.js";
import { ensureProfile } from "./users.js";
import { awardKey, awardXp, type ScoredEvent } from "./xp.js";

const Common = z.object({
  // Generated by the app when the event happens, so a retried upload is stored once.
  id: z.uuid(),
  // e.g. "es-v1", or "es-duel" for a duel. Checked against real content once it's in the database.
  clipId: z.string().regex(/^[a-z]{2}-[a-z0-9]{1,16}$/, "must look like es-v1"),
  occurredAt: z.iso.datetime({ offset: true }),
});

const kind = <K extends string, P extends z.ZodRawShape>(name: K, payload: P) =>
  Common.extend({ kind: z.literal(name), payload: z.object(payload).strict() }).strict();

// What the app reports. Each kind has a strict payload, so nothing unexpected gets stored.
// Scores and XP are never taken from here: the server derives them from these facts.
const Event = z.discriminatedUnion("kind", [
  kind("clip_viewed", {}),
  kind("card_flipped", {}),
  kind("quiz_answered", { firstTry: z.boolean() }),
  // The browser scores speech locally, so the server can only bound it, not check it.
  kind("speech_scored", { score: z.int().min(0).max(100) }),
  kind("review_graded", { grade: z.enum(["again", "good", "easy"]) }),
  kind("clip_saved", { saved: z.boolean() }),
  kind("duel_finished", { won: z.boolean() }),
]);

export const MAX_BATCH = 100;
// The app queues events while offline. Older ones are refused as stale.
const MAX_AGE_MS = 30 * 24 * 60 * 60 * 1000;
// Allow for phones whose clocks run a little fast.
const MAX_SKEW_MS = 5 * 60 * 1000;

// A malformed batch is a bug in the app, so the whole request fails with a 400.
export const EventBatch = z.object({ events: z.array(Event).min(1).max(MAX_BATCH) }).strict();

export type AppEvent = z.infer<typeof Event>;

/**
 * Why an otherwise well-formed event can't be stored, or null if it can. These are refused
 * one by one rather than failing the batch: a single stale event must not wedge the app's
 * upload queue behind it forever.
 */
export function refusal(e: AppEvent, now = Date.now()): string | null {
  const t = Date.parse(e.occurredAt);
  if (t > now + MAX_SKEW_MS) return "occurred_in_future";
  if (t < now - MAX_AGE_MS) return "too_old";
  return null;
}

// An offline session uploaded later still counts on the day it happened, but no more than this
// far back, so faking timestamps can rescue at most a one-day streak.
const MAX_BACKDATE = "36 hours";

/**
 * Stores events for one learner and awards their XP, all in one transaction. Events already
 * stored (a retry, or a repeat within the batch) are skipped, so uploading the same batch twice
 * has no extra effect. Returns the ids that were new.
 */
export async function storeEvents(db: Db, userId: string, events: AppEvent[]): Promise<string[]> {
  if (!events.length) return [];
  await ensureProfile(db, userId);

  return db.transaction(async (tx) => {
    // Lock the learner so concurrent uploads are scored one after another. Otherwise two
    // could both see "not yet earned today" and award the same XP twice.
    const { rows: users } = await tx.query<{ timezone: string; daily_goal_xp: number }>(
      "select timezone, daily_goal_xp from app.users where id = $1 for update",
      [userId],
    );
    const { timezone, daily_goal_xp: goal } = users[0]!;

    const { rows: inserted } = await tx.query<{ id: string; kind: string; clip_id: string; payload: Record<string, unknown>; day: string }>(
      `insert into app.events (user_id, id, kind, clip_id, payload, occurred_at, day)
       select $1, e.id, e.kind, e.clip_id, e.payload, e.occurred_at,
              (greatest(least(e.occurred_at, now()), now() - interval '${MAX_BACKDATE}') at time zone $7)::date
         from unnest($2::uuid[], $3::text[], $4::text[], $5::jsonb[], $6::timestamptz[])
              as e(id, kind, clip_id, payload, occurred_at)
       on conflict (user_id, id) do nothing
       returning id, kind, clip_id, payload, day::text`,
      [
        userId,
        events.map((e) => e.id),
        events.map((e) => e.kind),
        events.map((e) => e.clipId),
        events.map((e) => JSON.stringify(e.payload)),
        events.map((e) => e.occurredAt),
        timezone,
      ],
    );
    if (!inserted.length) return [];

    // Keep the batch's own order so the first of several repeats is the one that scores.
    const order = new Map(events.map((e, i) => [e.id, i]));
    const fresh: ScoredEvent[] = inserted
      .map((r) => ({ id: r.id, kind: r.kind, clipId: r.clip_id, payload: r.payload, day: r.day }))
      .sort((a, b) => order.get(a.id)! - order.get(b.id)!);

    const days = [...new Set(fresh.map((e) => e.day))];
    const { rows: prior } = await tx.query<{ kind: string; clip_id: string; day: string }>(
      `select distinct kind, clip_id, day::text from app.events
        where user_id = $1 and xp_awarded > 0 and day = any($2::date[])`,
      [userId, days],
    );
    const xp = awardXp(fresh, new Set(prior.map((r) => awardKey({ kind: r.kind, clipId: r.clip_id, day: r.day }))));

    const scored = fresh.filter((e) => xp.get(e.id)! > 0);
    if (scored.length) {
      await tx.query(
        `update app.events e set xp_awarded = v.xp
           from unnest($2::uuid[], $3::int[]) as v(id, xp)
          where e.user_id = $1 and e.id = v.id`,
        [userId, scored.map((e) => e.id), scored.map((e) => xp.get(e.id))],
      );
      const perDay = new Map<string, number>();
      for (const e of scored) perDay.set(e.day, (perDay.get(e.day) ?? 0) + xp.get(e.id)!);
      await tx.query(
        `insert into app.daily_progress as d (user_id, day, xp, goal_hit)
         select $1, v.day, v.xp, v.xp >= $4 from unnest($2::date[], $3::int[]) as v(day, xp)
         on conflict (user_id, day) do update
           set xp = d.xp + excluded.xp,
               goal_hit = d.goal_hit or d.xp + excluded.xp >= $4`,
        [userId, [...perDay.keys()], [...perDay.values()], goal],
      );
    }
    return fresh.map((e) => e.id);
  });
}
